static void bucket_launch_low_orbit_closure18_inverse(const StorageLayout&layout,int threads=256,int gx=16,int gy=8){dim3 block(threads),grid(gx,gy,unsigned(layout.main_blocks.size()));for(int p=LOW_LUT_K;p>=1;--p){bucket_low_orbit_closure18_inverse_kernel<<<grid,block>>>(p);ck(cudaGetLastError(),"bucket low orbit closure18 inverse");}}
static void bucket_launch_high_orbit_closure18_inverse(const StorageLayout&layout,int threads=256,int gx=16,int gy=8){dim3 block(threads),grid(gx,gy,unsigned(layout.main_blocks.size()));for(int p=TARGET_W-1;p>=LOW_LUT_K+1;--p){bucket_high_orbit_closure18_inverse_kernel<<<grid,block>>>(p);ck(cudaGetLastError(),"bucket high orbit closure18 inverse");}}
static void bucket_launch_reverse_low_split18_inverse(const StorageLayout&layout,int threads=256,int gx=16,int gy=8){dim3 block(threads),grid(gx,gy,unsigned(layout.main_blocks.size()));for(int p=1;p<=LOW_LUT_K;++p){bucket_reverse_low_split18_inverse_kernel<<<grid,block>>>(p);ck(cudaGetLastError(),"bucket reverse low split18 inverse");}}
static void bucket_launch_reverse_high_split18_inverse(const StorageLayout&layout,int threads=256,int gx=16,int gy=8){dim3 block(threads),grid(gx,gy,unsigned(layout.main_blocks.size()));for(int p=LOW_LUT_K+1;p<TARGET_W;++p){bucket_reverse_high_split18_inverse_kernel<<<grid,block>>>(p);ck(cudaGetLastError(),"bucket reverse high split18 inverse");}}
